// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DirectoryMembership) predicate.DirectoryMembership {
	return predicate.DirectoryMembership(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
